let z;
function fitToWidth(){
if(!outerWidth)return requestAnimationFrame(fitToWidth);
const z2=Math.round(outerWidth/innerWidth*100)/100;
if(z==z2)return;
z=z2;
const s=(document.body.clientWidth)/pageWidth*z,
l=Math.max(0,Math.round((document.body.clientWidth-pageWidth*s)/2)),
p=document.getElementById(`page-${pageBase}`);
p.style.transform=`scale(${s})`;
p.style.marginLeft=`${l}px`;
document.body.style.height=`${pageHeight*s}px`;
document.body.style.overflowX=z<=1?"hidden":"auto";
}
